def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'D'
    last_me, last_op = history[-1]
    if n >= 95 and last_op == 'D':
        return 'D'
    if n == 99:
        return 'D'
    if n >= 8:
        recent = history[-8:]
        if all(h[0] == 'C' for h in recent) and all(h[1] == 'D' for h in recent):
            return 'D'
    return 'C'
